ALTER TABLE public.notifications ADD COLUMN bell_actor uuid, ADD COLUMN bell_demand uuid;
CREATE FUNCTION public.bell_route_within_radius(_post uuid,_demand uuid,_actor uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v record; d public.vehicle_bell_demands; radius double precision; BEGIN IF _actor IS NULL THEN RETURN false; END IF; IF _post IS NOT NULL THEN SELECT from_lat,from_lng,to_lat,to_lng INTO v FROM public.vehicle_post_points WHERE post_id=_post; ELSE SELECT * INTO d FROM public.vehicle_bell_demands WHERE id=_demand; IF d.post_id IS NOT NULL THEN SELECT from_lat,from_lng,to_lat,to_lng INTO v FROM public.vehicle_post_points WHERE post_id=d.post_id; ELSE SELECT g.from_lat,g.from_lng,g.to_lat,g.to_lng INTO v FROM public.vehicle_route_points g JOIN public.vehicle_route_preferences r ON r.id=g.route_id AND r.user_id=g.user_id WHERE r.user_id=d.user_id AND r.enabled AND lower(trim(r.from_place))=lower(trim(d.from_place)) AND lower(trim(r.to_place))=lower(trim(d.to_place)) LIMIT 1; END IF; END IF; IF NOT FOUND THEN RETURN false; END IF; radius:=public.straight_line_km(v.from_lat,v.from_lng,v.to_lat,v.to_lng)*0.20; RETURN EXISTS(SELECT 1 FROM public.vehicle_route_points g JOIN public.vehicle_route_preferences r ON r.id=g.route_id AND r.user_id=g.user_id WHERE r.user_id=_actor AND r.enabled AND public.straight_line_km(g.from_lat,g.from_lng,v.from_lat,v.from_lng)<=radius AND public.straight_line_km(g.to_lat,g.to_lng,v.to_lat,v.to_lng)<=radius); END $$;
REVOKE ALL ON FUNCTION public.bell_route_within_radius(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.bell_route_within_radius(uuid,uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.route_only_vehicle_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN IF coalesce(current_setting('app.bell_notice',true),'')='interest' THEN IF NEW.post_id IS NOT NULL THEN SELECT * INTO p FROM public.posts WHERE id=NEW.post_id AND module='vehicle'; IF p.id IS NOT NULL THEN NEW.message:=public.vehicle_bell_route(p.from_place,p.to_place); NEW.vehicle_bell:=true; END IF; END IF; IF NEW.vehicle_bell THEN NEW.bell_actor:=auth.uid(); NEW.bell_demand:=nullif(current_setting('app.vehicle_bell_demand',true),'')::uuid; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.ring_vehicle_board(_demand uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.vehicle_bell_demands; caller uuid:=auth.uid(); target uuid; already_rang boolean; previous text:=coalesce(current_setting('app.bell_notice',true),''); prior_demand text:=coalesce(current_setting('app.vehicle_bell_demand',true),''); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) OR NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; SELECT * INTO d FROM public.vehicle_bell_demands WHERE id=_demand FOR UPDATE; IF d.id IS NULL OR NOT public.account_allowed(d.user_id) THEN RAISE EXCEPTION 'DEMAND_UNAVAILABLE'; END IF; IF d.user_id=caller THEN RETURN NULL; END IF; SELECT EXISTS(SELECT 1 FROM public.vehicle_demand_chat_pairs WHERE demand_id=d.id AND member_id=caller AND board_rang_at IS NOT NULL) INTO already_rang; target:=public.open_vehicle_demand_chat(d.id); IF NOT already_rang THEN UPDATE public.vehicle_demand_chat_pairs SET board_rang_at=now() WHERE demand_id=d.id AND member_id=caller; PERFORM set_config('app.bell_notice','interest',true); PERFORM set_config('app.vehicle_bell_demand',d.id::text,true); PERFORM 1 FROM public.profiles WHERE id=target FOR UPDATE; INSERT INTO public.notifications(user_id,message,vehicle_bell) VALUES(target,public.vehicle_bell_route(d.from_place,d.to_place),true); IF NOT EXISTS(SELECT 1 FROM public.messages WHERE sender_id=caller AND receiver_id=target AND post_id IS NULL) THEN INSERT INTO public.messages(sender_id,receiver_id,body) VALUES(caller,target,'హాయ్ · Hi'); END IF; PERFORM set_config('app.bell_notice',previous,true); PERFORM set_config('app.vehicle_bell_demand',prior_demand,true); END IF; RETURN target; END $$;
CREATE OR REPLACE FUNCTION public.notification_delivery_allowed(_user uuid,_notice uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.uid()=_user OR auth.role()='service_role') AND (public.paid_alert_ready(_user) OR EXISTS(SELECT 1 FROM public.free_work_notice_queue WHERE user_id=_user AND notification_id=_notice)) AND EXISTS(SELECT 1 FROM public.notifications n WHERE n.id=_notice AND n.user_id=_user AND (NOT n.vehicle_bell OR public.bell_route_within_radius(n.post_id,n.bell_demand,n.bell_actor))); $$;
COMMENT ON COLUMN public.notifications.bell_actor IS 'Private explicit bell actor for fail-closed selected-coordinate radius checks; not a public identity.';